import{_ as p,a0 as d,w as a,s as l,I as i,x as o,a1 as t,A as n,ao as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const U=JSON.parse('{"title":"如何在Docker容器中運行GUI程序 | LCTT x X-CMD","titleTemplate":false,"description":"如何在Docker容器中運行GUI程序 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在Docker容器中運行GUI程序 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在Docker容器中運行GUI程序 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150409 How to Run GUI Apps in a Docker Container","title":"如何在Docker容器中運行GUI程序","tag":"201504","desc":""},"relativePath":"201504/20150409 How to Run GUI Apps in a Docker Container.md","filePath":"[post].md"}'),c={name:"201504/20150409 How to Run GUI Apps in a Docker Container.md"};function k(u,e,f,m,D,x){const r=d("Link");return a(),l("div",null,[e[16]||(e[16]=i("h1",{id:"如何在docker容器中運行gui程序",tabindex:"-1"},[o("如何在Docker容器中運行GUI程序 "),i("a",{class:"header-anchor",href:"#如何在docker容器中運行gui程序","aria-label":"Permalink to “如何在Docker容器中運行GUI程序”"},"​")],-1)),i("p",null,[e[1]||(e[1]=o("各位，今天我們將學習如何在",-1)),t(r,{href:"http://docker.io/"},{default:n(()=>[...e[0]||(e[0]=[o("Docker",-1)])]),_:1}),e[2]||(e[2]=o("之中運行GUI程序。我們可以輕易地在Docker容器中運行大多數GUI程序且不出錯。Docker是一個開源項目，提供了一個打包、分發和運行任意程序的輕量級容器的開放平台。它沒有語言支持、框架或者打包系統的限制，並可以運行在任何地方、任何時候，從小型的家用電腦到高端的服務器都可以運行。這讓人們可以打包不同的包用於部署和擴展網絡應用，資料庫和後端服務而不必依賴於特定的棧或者提供商。",-1))]),e[17]||(e[17]=s(`<p>下面是我們該如何在Docker容器中運行GUI程序的簡單步驟。本教程中，我們會用Firefox作為例子。</p><h3 id="_1-安裝-docker" tabindex="-1">1. 安裝 Docker <a class="header-anchor" href="#_1-安裝-docker" aria-label="Permalink to “1. 安裝 Docker”">​</a></h3><p>在開始前，我們首先得確保在Linux主機中已經安裝了Docker。這裏，我運行的是CentOS 7 主機，我們將運行yum管理器和下面的命令來安裝Docker。</p><pre><code># yum install docker
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/installing-docker.png" alt=""></p><pre><code># systemctl restart docker.service
</code></pre><h3 id="_2-創建-dockerfile" tabindex="-1">2. 創建 Dockerfile <a class="header-anchor" href="#_2-創建-dockerfile" aria-label="Permalink to “2. 創建 Dockerfile”">​</a></h3><p>現在，Docker守護進程已經在運行中了，我們現在準備創建自己的Firefox Docker容器。我們要創建一個Dockerfile，在其中我們要輸入需要的配置來創建一個可以工作的Firefox容器。為了運行 Docker 鏡像我們需要使用最新版本的CentOS。要創建 Docker 鏡像，我們需要用文本編輯器創建一個名為Dockerfile的文件。</p><pre><code># nano Dockerfile
</code></pre><p>接着，在Dockerfile中添加下面的行並保存。</p><pre><code>#!/bin/bash
FROM centos:7
RUN yum install -y firefox
# 用你自己的 uid /gid 替換下面的0
RUN export uid=0 gid=0
RUN mkdir -p /home/developer
RUN echo &quot;developer:x:\${uid}:\${gid}:Developer,,,:/home/developer:/bin/bash&quot; &gt;&gt; /etc/passwd
RUN echo &quot;developer:x:\${uid}:&quot; &gt;&gt; /etc/group
RUN echo &quot;developer ALL=(ALL) NOPASSWD: ALL&quot; &gt;&gt; /etc/sudoers
RUN chmod 0440 /etc/sudoers
RUN chown \${uid}:\${gid} -R /home/developer

USER developer
ENV HOME /home/developer
CMD /usr/bin/firefox
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/Dockerfile-GUI.png" alt=""></p><p><strong>注意：在第四行的配置中，用你自己的用户和組id來替換0。 我們可以用下面的命令在shell或者終端中得到uid和gid。</strong></p><pre><code>#  id $USER
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/user-id.png" alt=""></p><h3 id="_3-構造docker容器" tabindex="-1">3. 構造Docker容器 <a class="header-anchor" href="#_3-構造docker容器" aria-label="Permalink to “3. 構造Docker容器”">​</a></h3><p>下面我們就要根據上面的Dockerfile構建一個容器。它會安裝firefox瀏覽器和它需要的包。它接着會設置用户權限並讓它可以工作。這裏鏡像名是firefox，你可以根據你的需要命名。</p><pre><code># docker build --rm -t firefox .
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/building-firefox-docker.png" alt=""></p><h3 id="_4-運行docker容器" tabindex="-1">4. 運行Docker容器 <a class="header-anchor" href="#_4-運行docker容器" aria-label="Permalink to “4. 運行Docker容器”">​</a></h3><p>現在，如果一切順利，我們現在可以在運行在CentOS 7鏡像中的Docker容器裏面運行我們的GUI程序也就是Firefox瀏覽器了。</p><pre><code># docker run -ti --rm -e DISPLAY=$DISPLAY -v /tmp/.X11-unix:/tmp/.X11-unix firefox
</code></pre><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>在Docker容器中運行GUI程序是一次很棒的體驗，它對你的主機文件系統沒有任何的傷害。它完全依賴你的Docker容器。本教程中，我嘗試了CentOS 7 Docker中的Firefox。我們可以用這個技術嘗試更多的GUI程序。如果你有任何問題、建議、反饋請在下面的評論欄中寫下來，這樣我們可以提升或更新我們的內容。謝謝！</p><hr>`,25)),i("p",null,[e[4]||(e[4]=o("via: ",-1)),t(r,{href:"http://linoxide.com/linux-how-to/run-gui-apps-docker-container/"},{default:n(()=>[...e[3]||(e[3]=[o("http://linoxide.com/linux-how-to/run-gui-apps-docker-container/",-1)])]),_:1})]),i("p",null,[e[8]||(e[8]=o("作者：",-1)),t(r,{href:"http://linoxide.com/author/arunp/"},{default:n(()=>[...e[5]||(e[5]=[o("Arun Pyasi",-1)])]),_:1}),e[9]||(e[9]=o(" 譯者：",-1)),t(r,{href:"https://github.com/geekpi"},{default:n(()=>[...e[6]||(e[6]=[o("geekpi",-1)])]),_:1}),e[10]||(e[10]=o(" 校對：",-1)),t(r,{href:"https://github.com/wxy"},{default:n(()=>[...e[7]||(e[7]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[13]||(e[13]=o("本文由 ",-1)),t(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[11]||(e[11]=[o("LCTT",-1)])]),_:1}),e[14]||(e[14]=o(" 原創翻譯，",-1)),t(r,{href:"http://linux.cn/"},{default:n(()=>[...e[12]||(e[12]=[o("Linux中國",-1)])]),_:1}),e[15]||(e[15]=o(" 榮譽推出",-1))])])}const b=p(c,[["render",k]]);export{U as __pageData,b as default};
